{"results": [{"id": "hp_doc_d791c2276b742ea2cad126d720423ddd7b70eb0cc6f27245685498e81bda25d5", "title": "McCluer South-Berkeley High School", "text": "McCluer South-Berkeley High School is a secondary school located at 201 Brotherton Lane in the city of Ferguson, Missouri a suburb of St. Louis. Located in the Ferguson-Florissant School District McCluer South Berkeley is the newest secondary school. MSB educates students from the cities of Cool Valley, Ferguson, Kinloch and Berkeley.", "score": 29.4787}, {"id": "hp_doc_12fb069538a39dcc50d5007d221913626f9133fccd83dcdf437f6a4818ba8f6a", "title": "McCluer High School", "text": "McCluer High School is a high school located in Florissant, Missouri. The principal is Cedric Gerald, and the school is the home of the McCluer Comets. It is a part of the Ferguson-Florissant School District.", "score": 13.2469}, {"id": "hp_doc_0a9a87d459e7fe3cfd0f60546e4fa1ae9cb27afbba82458041674b92bffd25d7", "title": "McCluer North High School", "text": "McCluer North High School (founded 1971) is a public school in Florissant, Missouri, United States. The McCluer North campus is centrally located in the Ferguson-Florissant School District. Located in a residential area, the campus is bounded by Waterford Drive, St. Catherine and Parker Road. Facing the site is the Florissant Civic Center and its 20 acre park-like setting.", "score": 12.2961}], "remaining_searches": 2}
